                    float angle = 90.0;
                    float actualStrength = amzp_strength/4.0/amzp_iter;
                    float2 texelSize = 1.0 / float2((screen.zw/2.0));
                    float rad = angle * 0.0174533;
                    float2 velocity = float2(cos(rad)*actualStrength,-sin(rad)*actualStrength);
                    float speed = length(velocity / texelSize);
                    int nSamples = int(clamp(speed, 2.01, 100.01));
                    float4 outColor = amzTexture(3,amzScreenNorm().st);
                    float4 manColor = amzTexture(0,amzScreenNorm().st);
                    for(int i=1; i<nSamples; i++ ) {
                        float2 offset = velocity * (float(i) / float(nSamples - 1));
                        outColor += amzTexture(3, amzScreenNorm().st+offset);
                        outColor += amzTexture(3, amzScreenNorm().st-offset);
                    }
                    float4 result = outColor/float(nSamples*2-1);
                    float4 blured = (manColor-result)*amzp_brig;
                        float red = blured.r;
                        float green = blured.g;
                        float blue = blured.g;
                        float all = (red+green+blue)/3.;
                        float4 whiteColour = float4(0.0);
                        if ((amzp_whiteonly>0.5)) {
                        whiteColour = float4(all, all, all, 1.0) * texColor.a;
                        } else {
                        whiteColour = blured;
                        }
